            } else {
                assert(fits(m, u + 1, used)) by {
                    assert forall |a: int, b: int| #[trigger] m.contains((a, b)) implies
                        a >= u + 1 && 0 <= b < used.len() && !used[b] by {
                        assert(m.contains((a, b)));
                        assert(a >= u);
                        if a == u {
                            assert(m.contains((u, b)));
                        }
                    }
                }
                lemma_upper(g, m, u + 1, used);
            }
        }
    }

