                    assert forall |e1: (int, int), e2: (int, int)|
                        #[trigger] m.contains(e1) && #[trigger] m.contains(e2) && e1 != e2 implies
                        (e1.0 != e2.0 && e1.1 != e2.1) by {
                        if e1 == (u, v) {
                            if e2 != (u, v) {
                                assert(m1.contains(e2));
                                assert(e2.0 >= u + 1);
                                assert(e2.1 != v);
                            }
                        } else if e2 == (u, v) {
                            assert(m1.contains(e1));
                            assert(e1.0 >= u + 1);
                            assert(e1.1 != v);
                        } else {
