use vstd::prelude::*;
verus! {
    pub open spec fn pm2(g: Seq<Seq<int>>, u: int, j: int) -> int
        recommends 0 <= u < g.len(), 0 <= j <= g[u].len()
        decreases g.len() - u, j
    {
        if j <= 0 { 0 } else { pm2(g, u, j - 1) + best2(g, u + 1) }
