use vstd::prelude::*;
verus! {
    fn rs(n: usize, u: usize, used: &mut Vec<bool>) -> (r: usize)
        requires u <= n,
        ensures r as int <= 1000,
        decreases n - u
    {
        if u >= n { return 0; }
        let mut acc: usize = 0;
        let mut j: usize = 0;
        while j < 3
            invariant 0 <= j <= 3, u < n, acc <= 1000,
            decreases 3 - j
        {
            let r = rs(n, u + 1, used);
            if r + 1 > acc { acc = r + 1; }
            j += 1;
        }
        acc
    }
    fn main() {}
}
